//! 演出覆盖：自定义动画 (`game/animation/*.json`) 与 `-enter` / `-exit` /
//! `setTransition` / `setAnimation` / `setTempAnimation` / `setComplexAnimation`。
//!
//! 关键帧时序的口径来自渲染器：一帧的 `t_us` 是**这段过渡的开始**，`enter_ms` 是
//! 到达本帧还要往前走多久 (`key_progress`)。所以第 i 帧落在第 i-1 段结束处，
//! 第一帧是起点状态、时长为 0。

use std::path::PathBuf;

use webgal_video_export::{
    config::ExportConfig,
    plan::{BackgroundKey, FigureKey, ParticleKind, Plan},
    project::Project,
    script::{ChoicePolicy, StartOptions, compile_with},
};

fn plan_for(scene: &str) -> Plan {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/animation");
    let project = Project::open(path).expect("open animation fixture");
    let config = ExportConfig::default();
    let policy = ChoicePolicy::new(&config.choices);
    let start = StartOptions {
        scene: Some(scene.to_owned()),
        label: None,
    };
    compile_with(&project, &config, &policy, &start).expect("compile")
}

fn has_warning(plan: &Plan, code: &str) -> bool {
    plan.warnings.iter().any(|warning| warning.code == code)
}

fn x(key: &BackgroundKey) -> Option<i32> {
    key.transform.position.and_then(|position| position.x)
}

fn figure_x(key: &FigureKey) -> Option<i32> {
    key.transform.position.and_then(|position| position.x)
}

#[test]
fn default_enter_keeps_the_single_fade_key() {
    let plan = plan_for("default");
    assert_eq!(plan.background.len(), 1);
    let key = &plan.background[0];
    assert_eq!(key.t_us, 0);
    assert_eq!(key.enter_ms, 1500);
    assert!(key.snap_transform);
    assert!(plan.warnings.is_empty(), "未写 -enter 时不应有警告");
}

#[test]
fn named_enter_expands_the_animation_frames() {
    let plan = plan_for("enter");
    assert_eq!(plan.background.len(), 2, "enter-from-left 有两帧");

    let start = &plan.background[0];
    assert_eq!(start.t_us, 0);
    assert_eq!(start.enter_ms, 0, "起点状态立刻生效");
    assert_eq!(start.alpha, 0.0);
    assert_eq!(start.transform.blur, Some(5));
    // -50 × 0.75 (1920 / 2560) = -37.5 → -38
    assert_eq!(x(start), Some(-38));

    let end = &plan.background[1];
    assert_eq!(end.t_us, 0, "第二帧是这段过渡的起点");
    assert_eq!(end.enter_ms, 500);
    assert_eq!(end.alpha, 1.0);
    assert_eq!(end.transform.blur, Some(0));
    assert_eq!(x(end), Some(0));
    assert_eq!(end.ease, "", "未写 ease 时交给渲染器的默认 (easeInOut)");
    assert!(!end.snap_transform, "后续帧要插值");
}

#[test]
fn enter_animation_end_state_replaces_transform() {
    let plan = plan_for("state");
    let last = plan.background.last().expect("setTransform key");
    // 动画终态 position.x = 0, 之后 setTransform 的 x=100 是相对基准的覆盖。
    assert_eq!(x(last), Some(75));
    assert_eq!(last.enter_ms, 200);
    assert_eq!(
        plan.background.len(),
        3,
        "两帧动画 + 一个 setTransform 关键帧"
    );
}

