fn enter_animation_advances_the_timeline() {
    let plan = plan_for("advance");
    let last = plan.background.last().expect("setTransform key");
    assert_eq!(last.t_us, 500_000, "enter-from-left 总时长 500ms");
}

#[test]
fn set_animation_emits_keys_at_segment_starts() {
    let plan = plan_for("set");
    assert_eq!(plan.background.len(), 5, "1 个换背景 + shake 的 4 帧");
    let keys = &plan.background[1..];
    assert_eq!((keys[0].t_us, keys[0].enter_ms), (0, 0));
    assert_eq!((keys[1].t_us, keys[1].enter_ms), (0, 250));
    assert_eq!((keys[2].t_us, keys[2].enter_ms), (250_000, 500));
    assert_eq!((keys[3].t_us, keys[3].enter_ms), (750_000, 250));
    // 位移按 0.75 缩放; 终态回到 0。
    assert_eq!(x(&keys[1]), Some(-75));
    assert_eq!(x(&keys[2]), Some(75));
    assert_eq!(x(&keys[3]), Some(0));
}

#[test]
fn transform_from_default_drops_the_current_state() {
    let current = plan_for("set_current");
    let current_key = current.background.last().expect("shake key");
    assert_eq!(current_key.alpha, 0.5, "默认从当前状态起算");

    let reset = plan_for("set_from_default");
    let reset_key = reset.background.last().expect("shake key");
    assert_eq!(reset_key.alpha, 1.0, "-transformFrom=default 从默认值起算");
}

